mapper.select:
SELECT email, briefing_day, last_briefing_cycle_start
FROM tbl_ledger_setting
WHERE email = #{email}

mapper.update:
UPDATE tbl_ledger_setting
SET briefing_day = #{briefingDay}
WHERE email = #{email}

UPDATE tbl_ledger_setting
SET last_briefing_cycle_start = #{cycleStart}
WHERE email = #{email}
